// Крупные временные знаки шапки для экранов 2 и 3 шага 0. Нарисованы вручную составителем экранов,
// не художником; подпись «временный знак» стоит на странице. Линия — «чернила» темы, одна плоская
// заливка из палитры рисунков (08 § 3.2.1, § 7.3). Людей нет: Иисус Христос не изображается, Бог — тоже.
// ПРОТОТИП: в продукт не переносится.
(function () {
  // волна от x0 до x1 на высоте y: полуволны шириной w, высотой a
  function волна(x0, x1, y, w = 20, a = 4) {
    let d = `M${x0} ${y}`; let вверх = true;
    for (let x = x0; x < x1; x += w) { d += ` q${w / 2} ${вверх ? -a : a} ${w} 0`; вверх = !вверх; }
    return d;
  }

  // Ковчег на водах. Корпус: длина к высоте 10 : 1 и видимая ширина — по Быт 6:15
  // («длина ковчега триста локтей; ширина его пятьдесят локтей, а высота его тридцать локтей»);
  // дверь с боку — Быт 6:16 («дверь в ковчег сделай с боку его»). Кровли и окна нет: вид — условно.
  const ковчег = () => {
    const воды = волна(0, 400, 196, 25, 5);
    return `<svg class="знак знак--крупно знак-шапки" viewBox="0 0 400 300" preserveAspectRatio="xMidYMax slice" aria-hidden="true" focusable="false">
      <path class="з-охра" d="M60 176h260v26H60z M60 176l28-20h260l-28 20z M320 176l28-20v26l-28 20z"/>
      <path class="л" d="M60 176h260v26H60z M60 176l28-20h260l-28 20 M320 202l28-20v-26"/>
      <path class="л" d="M246 180h14v18h-14z"/>
      <path class="з-бирюза" d="${воды} V300 H0z"/>
      <path class="л" d="${воды}"/>
      <path class="л" d="${волна(40, 360, 226, 30, 5)}"/>
      <path class="л" d="${волна(110, 290, 254, 30, 5)}"/>
    </svg>`;
  };

  // Постель и кровля: кровля с проёмом и постель под ним (Мк 2:4 «раскрыли кровлю дома…
  // спустили постель»). Верёвок нет: в стихах их нет. Людей нет.
  const постель = () => `<svg class="знак знак--крупно знак-шапки" viewBox="0 0 600 260" preserveAspectRatio="xMidYMax slice" aria-hidden="true" focusable="false">
      <path class="л" d="M10 40h260v18H10z M330 40h260v18H330z"/>
      <path class="л" d="M270 46l9 4 M270 54l7 2 M330 46l-9 4 M330 54l-7 2"/>
      <path class="л" d="M40 58v192 M560 58v192 M0 250h600"/>
      <path class="з-олива" d="M236 140l124-8 4 18-124 8z"/>
      <path class="л" d="M236 140l124-8 4 18-124 8z M239 152l124-8"/>
    </svg>`;

  // Малый знак «голубь» для карточки (сетка 48): птица и масличный лист —
  // Быт 8:11 «свежий масличный лист во рту у него».
  const голубь = (класс = '') => `<svg class="знак ${класс}" viewBox="2 8 44 30" preserveAspectRatio="xMinYMid meet" aria-hidden="true" focusable="false">
      <path class="з-индиго" d="M10 24c4-6 12-8 18-6l8-4 2 4-6 4c2 6-4 12-14 12l-10 4 2-6z"/>
      <path class="л" d="M10 24c4-6 12-8 18-6l8-4 2 4-6 4c2 6-4 12-14 12l-10 4 2-6z M16 26c4 2 8 2 12-2"/>
      <path class="з-олива" d="M38 16c4-2 6 0 6 2-3 2-5 1-6-2z"/>
      <path class="л" d="M38 16c4-2 6 0 6 2-3 2-5 1-6-2z"/>
    </svg>`;

  window.ЗНАКИ_ИСТОРИИ = { ковчег, постель, голубь };
})();
